Let me design the game API:

```js
// script.js
const BOARD_SIZE = 20;
const TICK_MS = 150;

class SnakeGame {
  constructor(boardSize) {
    this.boardSize = boardSize;
    this.reset();
  }
  reset() {
    const c = Math.floor(this.boardSize / 2);
    this.snake = [ {x: c, y: c}, {x: c-1, y: c}, {x: c-2, y: c} ]; // head first, facing right
    this.direction = {x: 1, y: 0};
    this.pendingDirection = this.direction; // or a queue
    this.score = 0;
    this.alive = true;
    this.food = this.spawnFood();
  }
  spawnFood() { ... random empty cell ... }
  setDirection(d) {
    // ignore reverse
    if (d.x === -this.direction.x && d.y === -this.direction.y) return;
    this.pendingDirection = d;
  }
  step() {
    if (!this.alive) return;
    this.direction = this.pendingDirection;
    const head = { x: this.snake[0].x + this.direction.x, y: this.snake[0].y + this.direction.y };
    // wall
    if (head.x < 0 || head.y < 0 || head.x >= this.boardSize || head.y >= this.boardSize) { this.alive = false; return; }
    // self: when not eating, the tail moves, so moving into the current tail cell is OK. Standard: check against body minus the last segment unless eating.
    const willEat = head.x === this.food.x && head.y === this.food.y;
    const body = willEat ? this.snake : this.snake.slice(0, -1);
    if (body.some(s => s.x === head.x && s.y === head.y)) { this.alive = false; return; }
    this.snake.unshift(head);
    if (willEat) { this.score += 1; this.food = this.spawnFood(); }
    else this.snake.pop();
  }
  render(ctx) { ... draw board, snake, food ... }
}

window.game = new SnakeGame(20);
```

Loop: use requestAnimationFrame with an accumulator, or setInterval. The spec says rAF or setInterval with a consistent tick rate. I'll use rAF with an accumulator for a smooth loop. But for step-ability in tests, `step()` must be callable manually. I'll structure it: the loop calls `game.step()` when the tick interval elapses.

For testing, it would be convenient to have a way to pause the auto-loop and step manually. I'll expose `window.game` and a `window.snake = { step, setDirection, ... }` controller. Let me design the page code:

```js
// controller
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const game = new SnakeGame(20);
window.game = game;

let lastTime = null;
let accumulator = 0;
function frame(t) {
  if (lastTime === null) lastTime = t;
  const dt = t - lastTime;
  lastTime = t;
  if (game.alive) {
    accumulator += dt;
    while (accumulator >= TICK_MS) {
      accumulator -= TICK_MS;
      game.step();
    }
  }
  render();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
```

