/* Minimal styling for ticket 1 — no neon polish yet. */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #111;
  color: #eee;
  font-family: "Helvetica Neue", Arial, sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
}

/* --- HUD --- */
#hud {
  width: 100%;
  max-width: 640px;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 16px;
}

#title {
  font-size: 20px;
  letter-spacing: 4px;
}

#score {
  font-size: 18px;
}

/* --- Board --- */
#board-wrap {
  position: relative;
}

#board {
  display: block;
  background: #1a1a1a;
  border: 2px solid #444;
}

/* --- Game-over overlay --- */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.6);
}

.overlay[hidden] {
  display: none;
}

.overlay-box {
  text-align: center;
  background: #222;
  border: 2px solid #555;
  padding: 24px 32px;
}

.overlay-box h2 {
  font-size: 24px;
  letter-spacing: 3px;
  margin-bottom: 12px;
}

.overlay-box p {
  font-size: 16px;
  margin-bottom: 16px;
}

#play-again {
  font-size: 16px;
  padding: 8px 20px;
  background: #333;
  color: #eee;
  border: 2px solid #888;
  cursor: pointer;
}

#play-again:hover {
  background: #444;
}

/* --- Footer hint --- */
#hint {
  margin-top: 12px;
  font-size: 13px;
  color: #999;
}

