  constructor(boardSize) {
    this.boardSize = boardSize;
    this.reset();
  }

  // Reset to initial state: length-3 snake at center, heading right.
  reset() {
    const c = Math.floor(this.boardSize / 2);
    // snake[0] is the head; body trails behind the direction of travel.
    this.snake = [
      { x: c, y: c },
      { x: c - 1, y: c },
      { x: c - 2, y: c },
    ];
    this.direction = { x: 1, y: 0 };
    this.pendingDirection = { x: 1, y: 0 };
    this.score = 0;
    this.alive = true;
    this.food = this.spawnFood();
  }

  // Pick a random cell that is not occupied by the snake.
  spawnFood() {
    const free = [];
    for (let y = 0; y < this.boardSize; y++) {
      for (let x = 0; x < this.boardSize; x++) {
        const occupied = this.snake.some((s) => s.x === x && s.y === y);
        if (!occupied) free.push({ x, y });
      }
    }
    if (free.length === 0) return null; // board full: snake wins
    return free[Math.floor(Math.random() * free.length)];
  }

  // Queue a direction change; reversing into the neck is ignored.
  setDirection(dir) {
    if (!this.alive) return;
    // Ignore direct reversal (and no-op duplicates).
    if (dir.x === -this.direction.x && dir.y === -this.direction.y) return;
    if (dir.x === this.direction.x && dir.y === this.direction.y) return;
    this.pendingDirection = dir;
  }

  // Advance the game by one tick. No-op when the game is over.
  step() {
    if (!this.alive) return;
    this.direction = this.pendingDirection;

    const head = this.snake[0];
    const next = { x: head.x + this.direction.x, y: head.y + this.direction.y };

    // Wall collision.
    if (next.x < 0 || next.y < 0 || next.x >= this.boardSize || next.y >= this.boardSize) {
      this.alive = false;
      return;
    }

    const willEat = this.food !== null && next.x === this.food.x && next.y === this.food.y;

    // Self collision. The tail cell vacates this tick unless the snake grows,
    // so exclude the last segment when not eating.
    const bodyToCheck = willEat ? this.snake : this.snake.slice(0, -1);
    if (bodyToCheck.some((s) => s.x === next.x && s.y === next.y)) {
      this.alive = false;
      return;
    }

    this.snake.unshift(next);
    if (willEat) {
      this.score += 1;
      this.food = this.spawnFood();
    } else {
      this.snake.pop();
    }
  }
}

// ---------------------------------------------------------------------------
// Renderer: draws a SnakeGame state onto a canvas context
// ---------------------------------------------------------------------------

const Renderer = {
  // Draw the whole board (background, food, snake) for one frame.
  render(ctx, game) {
    const size = game.boardSize * CELL_PX;

    // Background
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(0, 0, size, size);

    // Faint grid lines
    ctx.strokeStyle = "#262626";
    ctx.lineWidth = 1;
    for (let i = 1; i < game.boardSize; i++) {
      const p = i * CELL_PX + 0.5;
      ctx.beginPath();
      ctx.moveTo(p, 0);
      ctx.lineTo(p, size);
      ctx.moveTo(0, p);
      ctx.lineTo(size, p);
      ctx.stroke();
    }

    // Food
    if (game.food) {
      this.drawCell(ctx, game.food.x, game.food.y, "#e33");
    }

    // Snake: head slightly brighter than the body.
    for (let i = game.snake.length - 1; i >= 1; i--) {
      const s = game.snake[i];
      this.drawCell(ctx, s.x, s.y, "#3a9e3a");
    }
    const head = game.snake[0];
    this.drawCell(ctx, head.x, head.y, "#7cf27c");
  },

  // Draw a single cell rectangle at grid coordinates.
  drawCell(ctx, x, y, color) {
    ctx.fillStyle = color;
    // Small inset so segments read as separate blocks.
    ctx.fillRect(x * CELL_PX + 1, y * CELL_PX + 1, CELL_PX - 2, CELL_PX - 2);
  },
};

// ---------------------------------------------------------------------------
// Controller: DOM, input, and the game loop
// ---------------------------------------------------------------------------

(function main() {
  const canvas = document.getElementById("board");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score-value");
  const overlayEl = document.getElementById("gameover");
  const finalScoreEl = document.getElementById("final-score");
  const playAgainBtn = document.getElementById("play-again");

  // Size the canvas to match the logical board.
  const pixelSize = BOARD_SIZE * CELL_PX;
  canvas.width = pixelSize;
  canvas.height = pixelSize;

  const game = new SnakeGame(BOARD_SIZE);

  // Expose a small test/debug API on window.
  window.game = game;
  window.snake = {
    step: () => game.step(),
    setDirection: (dir) => game.setDirection(dir),
    reset: () => game.reset(),
    set food(cell) {
      game.food = cell;
    },
    // Pause/resume the automatic tick loop (used by self-tests).
    set paused(value) {
      paused = value;
    },
    get paused() {
      return paused;
    },
  };

  // --- Game over overlay -------------------------------------------------
  function showGameOver() {
    finalScoreEl.textContent = "Final score: " + game.score;
    overlayEl.hidden = false;
  }

  function hideGameOver() {
    overlayEl.hidden = true;
  }

  function updateScoreDisplay() {
    scoreEl.textContent = String(game.score);
  }

  // --- Input ---------------------------------------------------------------
  window.addEventListener("keydown", (e) => {
    const dir = KEY_DIRECTIONS[e.key];
    if (!dir) return;
    e.preventDefault(); // stop arrow keys / space from scrolling the page
    game.setDirection(dir);
  });

  playAgainBtn.addEventListener("click", () => {
    game.reset();
    updateScoreDisplay();
    hideGameOver();
  });

  // --- Game loop -----------------------------------------------------------
  // requestAnimationFrame with a fixed-step accumulator: game logic ticks
  // exactly every TICK_MS regardless of display refresh rate.
  let paused = false;
  let lastTime = null;
  let accumulator = 0;

  function frame(time) {
    if (lastTime === null) lastTime = time;
    let dt = time - lastTime;
    lastTime = time;
    if (dt > 250) dt = 250; // clamp after tab was backgrounded

    if (!paused && game.alive) {
      accumulator += dt;
      while (accumulator >= TICK_MS) {
        accumulator -= TICK_MS;
        game.step();
      }
    }

    if (!game.alive && overlayEl.hidden) {
      showGameOver();
    }

    Renderer.render(ctx, game);
    updateScoreDisplay();
    requestAnimationFrame(frame);
  }

  updateScoreDisplay();
  requestAnimationFrame(frame);
})();

