// and to what the viewport can hold.
function effectiveBoardSize(requested) {
  const n = Math.trunc(Number(requested));
  const clamped = Number.isFinite(n)
    ? Math.min(MAX_BOARD_SIZE, Math.max(MIN_BOARD_SIZE, n))
