      ctx.lineTo(p, size);
      ctx.moveTo(0, p);
      ctx.lineTo(size, p);
      ctx.stroke();
    }

    // Food
    if (game.food) {
      this.drawCell(ctx, game.food.x, game.food.y, cellPx, "#e33");
