// ---------------------------------------------------------------------------
// Renderer: draws a SnakeGame state onto a canvas context
// ---------------------------------------------------------------------------

const Renderer = {
  // Draw the whole board (background, food, snake) for one frame.
  render(ctx, game, cellPx) {
    const size = game.boardSize * cellPx;

    // Background
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(0, 0, size, size);

    // Faint grid lines
    ctx.strokeStyle = "#262626";
    ctx.lineWidth = 1;
    for (let i = 1; i < game.boardSize; i++) {
      const p = i * cellPx + 0.5;
      ctx.beginPath();
      ctx.moveTo(p, 0);
      ctx.lineTo(p, size);
      ctx.moveTo(0, p);
      ctx.lineTo(size, p);
      ctx.stroke();
    }

    // Food
    if (game.food) {
      this.drawCell(ctx, game.food.x, game.food.y, cellPx, "#e33");
    }

    // Snake: head slightly brighter than the body.
    for (let i = game.snake.length - 1; i >= 1; i--) {
      const s = game.snake[i];
      this.drawCell(ctx, s.x, s.y, cellPx, "#3a9e3a");
    }
    const head = game.snake[0];
    this.drawCell(ctx, head.x, head.y, cellPx, "#7cf27c");
  },

  // Draw a single cell rectangle at grid coordinates.
  drawCell(ctx, x, y, cellPx, color) {
    ctx.fillStyle = color;
    // Small inset so segments read as separate blocks.
    ctx.fillRect(x * cellPx + 1, y * cellPx + 1, cellPx - 2, cellPx - 2);
  },
};

