// In-page self-test (removed after verification).
// Scripted inputs + rule assertions + canvas pixel checks. Prints PASS/FAIL.
async () => {
  const out = [];
  let pass = true;
  const fail = (m, s) => { pass = false; out.push('FAIL ' + m + (s !== undefined ? ' | ' + JSON.stringify(s) : '')); };
  const assert = (cond, m, s) => { if (cond) out.push('ok ' + m); else fail(m, s); };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const S = window.snake;
  const $ = (id) => document.getElementById(id);
  const cv = $('board');
  const cx2 = cv.getContext('2d');
  const px = (x, y) => { const d = cx2.getImageData(x, y, 1, 1).data; return [d[0], d[1], d[2]]; };
  const near = (c, r, g2, b, tol) => Math.abs(c[0]-r) <= tol && Math.abs(c[1]-g2) <= tol && Math.abs(c[2]-b) <= tol;

  // ---- Game 1: eat, reverse ignore, wall death, game over, high score ----
  $('board-size').value = '10';
  $('start-btn').click();
  assert(S.state === 'ready', 'ready state after start', S.state);
  assert(S.game.boardSize === 10, 'board size 10', S.game.boardSize);
  window.dispatchEvent(new KeyboardEvent('keydown', { key: ' ' }));
  assert(S.state === 'playing', 'any key starts play', S.state);
  const g = S.game;
  assert(g.snake.length === 3, 'initial length 3', g.snake.length);
  assert(g.snake[0].x === 5 && g.snake[0].y === 5, 'head at center', g.snake[0]);

  S.stop(); // deterministic control
  S.food = { x: 6, y: 5 };
  g.step();
  assert(g.score === 1, 'score 1 after eat', g.score);
  assert(g.snake.length === 4, 'length 4 after eat', g.snake.length);
  assert(g.snake[0].x === 6 && g.snake[0].y === 5, 'head moved onto food', g.snake[0]);
  assert(g.food && !(g.food.x === 6 && g.food.y === 5), 'new food on free cell', g.food);

  S.food = null;
  g.setDirection({ x: -1, y: 0 }); // reverse: ignored
  g.step();
  assert(g.snake[0].x === 7 && g.snake[0].y === 5, 'reverse ignored', g.snake[0]);
  g.setDirection({ x: 0, y: -1 }); // up toward top wall
  for (let i = 0; i < 5 && g.alive; i++) g.step();
  assert(!g.alive, 'wall collision kills', g.snake[0]);

  S.start(); // let the rAF loop observe the death
  let waited = 0;
  while (S.state !== 'gameover' && waited < 1500) { await sleep(50); waited += 50; }
  assert(S.state === 'gameover', 'state gameover', S.state);
  assert(!$('gameover').hidden, 'game over overlay visible');
  assert($('final-score').textContent.indexOf('1') !== -1, 'final score shown', $('final-score').textContent);
  assert(S.sessionHighScore === 1, 'session high score 1', S.sessionHighScore);

  $('play-again').click();
  assert(S.state === 'menu', 'back to menu', S.state);
  assert($('menu-high').textContent.indexOf('1') !== -1, 'menu high score 1', $('menu-high').textContent);

  // ---- Game 2: self collision, tail-chase safe cell, WASD ----
  $('board-size').value = '10';
  $('start-btn').click();
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'a' }));
  assert(S.state === 'playing', 'WASD key starts play', S.state);
  const g2 = S.game;
  S.stop();
  S.food = { x: 6, y: 5 };
