  g2.setDirection({ x: -1, y: 0 }); g2.step(); // (5,4)
  g2.setDirection({ x: 0, y: 1 }); g2.step();  // (5,5): tail vacates, legal
  assert(g2.alive, 'tail-chase cell is safe', g2.snake[0]);
  g2.setDirection({ x: 1, y: 0 }); g2.step(); // (6,5): tail vacates, legal
  g2.setDirection({ x: 0, y: -1 }); g2.step(); // (6,4): body -> self collision
  assert(!g2.alive, 'self collision kills', g2.snake[0]);
  S.start();
  waited = 0;
  while (S.state !== 'gameover' && waited < 1500) { await sleep(50); waited += 50; }
  assert(S.state === 'gameover', 'game 2 gameover', S.state);
  assert($('final-score').textContent.indexOf('1') !== -1, 'game 2 final score', $('final-score').textContent);
  assert(S.sessionHighScore === 1, 'high score unchanged', S.sessionHighScore);
  $('play-again').click();

  // ---- Game 3: neon visual regression on the ready-screen render ----
  $('board-size').value = '10';
  $('start-btn').click();
  const c = S.cellPx;
  const cellCenter = (gx, gy) => [gx * c + Math.round(c / 2), gy * c + Math.round(c / 2)];
  const [bx, by] = cellCenter(0, 0);
  const [gx2, gy2] = [1 * c, Math.round(3 * c)];
  const [hx, hy] = cellCenter(5, 5);
  const [tx, ty] = cellCenter(3, 5);
