  await sleep(200); // let the rAF loop paint a couple of frames
  assert(near(px(bx, by), 3, 3, 8, 6), 'bg near-black', px(bx, by));
  const grid = px(gx2, gy2);
  assert(grid[1] > 8 || grid[2] > 8, 'grid line has cyan tint', grid);
