/* Snake — neon / geometric visual theme (ticket 3).
   Palette: near-black background, cyan #00f0ff, magenta #ff3df5,
   violet #7b3dff. All glows via text-shadow / box-shadow. */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  background:
    radial-gradient(1100px 750px at 50% 12%, rgba(0, 240, 255, 0.07), transparent 62%),
    radial-gradient(950px 700px at 50% 108%, rgba(255, 61, 245, 0.06), transparent 62%),
    #030308;
  color: #d8fbff;
  /* Clean geometric sans-serif stack (system fonts only, no web assets). */
  font-family: "Century Gothic", "Futura", "Avenir Next", "Trebuchet MS",
    "Segoe UI", Arial, sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
}

/* --- Start menu --- */
#menu {
  min-height: 100vh;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  text-align: center;
}

#menu[hidden] {
  display: none;
}

#title {
  font-size: 52px;
  font-weight: 700;
  letter-spacing: 14px;
  /* Offset so the glow does not clip the final letter. */
  text-indent: 14px;
  margin-bottom: 12px;
  color: #00f0ff;
  text-shadow:
    0 0 6px rgba(0, 240, 255, 0.9),
    0 0 22px rgba(0, 240, 255, 0.55),
    0 0 55px rgba(0, 240, 255, 0.35);
}

.menu-label {
  font-size: 15px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #6fd7e8;
}

#board-size {
  width: 90px;
  font-size: 18px;
  padding: 6px 8px;
  text-align: center;
  font-family: inherit;
  color: #eaffff;
  background: rgba(0, 20, 30, 0.85);
  border: 2px solid #0e7f95;
  border-radius: 6px;
  box-shadow:
    0 0 10px rgba(0, 240, 255, 0.18),
    inset 0 0 8px rgba(0, 240, 255, 0.12);
}

#board-size:focus {
  outline: none;
  border-color: #00f0ff;
  box-shadow:
    0 0 16px rgba(0, 240, 255, 0.55),
