}

#board-size::-webkit-outer-spin-button,
#board-size::-webkit-inner-spin-button {
  opacity: 1;
}

#size-note {
  font-size: 12px;
  letter-spacing: 1px;
  color: #4f8a99;
  margin-top: -6px;
}

#menu-high {
  font-size: 17px;
  letter-spacing: 1px;
  margin-top: 6px;
