/* Neon buttons: dark core, glowing border, brighter on hover/press. */
#start-btn,
#play-again {
  font-family: inherit;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  padding: 12px 30px;
  color: #00f0ff;
  background: rgba(0, 240, 255, 0.06);
