  color: #4f8a99;
  margin-top: 10px;
}

/* --- Game screen --- */
#game {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  min-height: 100vh;
  justify-content: center;
}

#game[hidden] {
